-- Generated by GMConverter. The client runtime for converted particle effects: it simulates each
-- effect's emitters from their exported definitions and draws them with the pixel shaders compiled
-- from their materials, on screenspace_general_8tex. Effects register with GMConverterFX.Register;
-- models register the effects their animations start with GMConverterFX.RegisterModel. Every add-on
-- GMConverter writes ships this file; the newest version loaded wins.
--
-- Effect space: +X forward, +Y left, +Z up, in Source units, attached to an entity's attachment.

local VERSION = 1

if GMConverterFX and (GMConverterFX.version or 0) >= VERSION then return end

local FX = GMConverterFX or {}
GMConverterFX = FX
FX.version = VERSION
FX.effects = FX.effects or {}
FX.models = FX.models or {}
FX.active = FX.active or {}

local random, floor, min, max, sqrt, sin, cos = math.random, math.floor, math.min, math.max, math.sqrt, math.sin, math.cos

--- Registers an effect: name -> { emitters = { ... } } as GMConverter writes it.
function FX.Register(name, definition)
	for index, emitter in ipairs(definition.emitters) do
		emitter.index = index
	end
	FX.effects[name] = definition
end

--- Registers the effects a model's sequences start: model path -> { [sequence] = { { time, effect, attachment }, ... } }.
function FX.RegisterModel(model, sequences)
	FX.models[string.lower(model)] = sequences
end

-- Curves are flat key lists: { t, v, t, v, ... } for numbers, { t, x, y, z, ... } for vectors, held past
-- their ends and linear between keys. A value is { min = keys, max = keys }; max is absent when equal.

local function sample1(keys, t)
	local n = #keys
	if n <= 2 or t <= keys[1] then return keys[2] end
	if t >= keys[n - 1] then return keys[n] end
	for i = 3, n - 1, 2 do
		if t <= keys[i] then
			local t0 = keys[i - 2]
			local f = (t - t0) / (keys[i] - t0)
			return keys[i - 1] + (keys[i + 1] - keys[i - 1]) * f
		end
	end
	return keys[n]
end

local function sample3(keys, t)
	local n = #keys
	if n <= 4 or t <= keys[1] then return keys[2], keys[3], keys[4] end
	if t >= keys[n - 3] then return keys[n - 2], keys[n - 1], keys[n] end
	for i = 5, n - 3, 4 do
		if t <= keys[i] then
			local t0 = keys[i - 4]
			local f = (t - t0) / (keys[i] - t0)
			return keys[i - 3] + (keys[i + 1] - keys[i - 3]) * f,
				keys[i - 2] + (keys[i + 2] - keys[i - 2]) * f,
				keys[i - 1] + (keys[i + 3] - keys[i - 1]) * f
		end
	end
	return keys[n - 2], keys[n - 1], keys[n]
end

local function floatAt(curve, t, r)
	local low = sample1(curve.min, t)
	if not curve.max then return low end
	return low + (sample1(curve.max, t) - low) * r
end

local function vectorAt(curve, t, rx, ry, rz)
	local x, y, z = sample3(curve.min, t)
	if not curve.max then return x, y, z end
	local hx, hy, hz = sample3(curve.max, t)
	return x + (hx - x) * rx, y + (hy - y) * ry, z + (hz - z) * rz
end

-- Materials: one per shader and vertex layout, created once.

local TEXTURE_PARAMS = { "$basetexture", "$texture1", "$texture2", "$texture3", "$texture4", "$texture5", "$texture6", "$texture7" }
local LINEAR_PARAMS = { "$linearread_basetexture", "$linearread_texture1", "$linearread_texture2", "$linearread_texture3",
	"$linearread_texture4", "$linearread_texture5", "$linearread_texture6", "$linearread_texture7" }

local materials = {}
local function material(def, layout)
	local key = def.shader .. "|" .. layout
	local cached = materials[key]
	if cached ~= nil then return cached or nil end
	local params = {
		["$pixshader"] = def.shader,
		["$vertexshader"] = layout == "mesh" and def.meshShader or def.spriteShader,
		["$cull"] = "0",
		["$depthtest"] = "1",
		["$vertexnormal"] = "1",
		["$vertexcolor"] = "1",
		["$tcsize0"] = "2", ["$tcsize1"] = "2", ["$tcsize2"] = "2", ["$tcsize3"] = "2",
	}
	for i, texture in ipairs(def.textures) do
		params[TEXTURE_PARAMS[i]] = texture[1]
		if texture[2] then params[LINEAR_PARAMS[i]] = "1" end
	end
	local mat = CreateMaterial("gmcfx_" .. def.shader .. "_" .. layout, "screenspace_general_8tex", params)
	if not mat or mat:IsError() then
		ErrorNoHalt("[GMConverter] Could not create effect material " .. def.shader .. "; screenspace_general_8tex needs Garry's Mod 2025.12 or newer.\n")
		materials[key] = false
		return nil
	end
	materials[key] = mat
	return mat
end

-- Mesh particles' models: triangle lists the exporter writes (count, then x y z u v per vertex).
local meshes = {}
local function particleMesh(path, mat)
	local cached = meshes[path]
	if cached ~= nil then return cached or nil end
	meshes[path] = false
	local f = file.Open(path, "rb", "GAME")
	if not f then
		ErrorNoHalt("[GMConverter] Missing effect mesh " .. path .. "\n")
		return nil
	end
	local count = f:ReadLong()
	local vertices = {}
	for i = 1, count do
		vertices[i] = { f:ReadFloat(), f:ReadFloat(), f:ReadFloat(), f:ReadFloat(), f:ReadFloat() }
	end
	f:Close()
	local imesh = Mesh(mat)
	mesh.Begin(imesh, MATERIAL_TRIANGLES, count / 3)
	local ok, err = pcall(function()
		for i = 1, count do
			local v = vertices[i]
			mesh.Position(Vector(v[1], v[2], v[3]))
			mesh.Normal(vector_up)
			mesh.TexCoord(0, v[4], v[5])
			mesh.AdvanceVertex()
		end
	end)
	mesh.End()
	if not ok then
		ErrorNoHalt("[GMConverter] Could not build effect mesh " .. path .. ": " .. tostring(err) .. "\n")
		return nil
	end
	meshes[path] = imesh
	return imesh
end

-- Source uploads render.SetModelLighting's ambient cube only when a model draws, so a hidden,
-- zero-scale model is drawn after setting it.
local commitModel
local function commitConstants()
	if not IsValid(commitModel) then
		commitModel = ClientsideModel("models/hunter/blocks/cube025x025x025.mdl", RENDERGROUP_OTHER)
		if not IsValid(commitModel) then return false end
		commitModel:SetNoDraw(true)
		commitModel:SetModelScale(0)
	end
	commitModel:DrawModel()
	return true
end

-- Instances

local function frameOf(instance)
	local ent = instance.entity
	if IsValid(ent) then
		if instance.attachment and instance.attachment > 0 then
			local point = ent:GetAttachment(instance.attachment)
			if point then return point.Pos, point.Ang end
		end
		return ent:GetPos(), ent:GetAngles()
	end
	return instance.pos or vector_origin, instance.ang or angle_zero
end

-- Particles raise events where they are born and die; emitters listening for them release theirs there
-- once every emitter has ticked. An event's position is in its emitter's space.
local function raise(instance, emitter, kind, p)
	local listeners = emitter.listeners and emitter.listeners[kind]
	if not listeners then return end
	local queue = instance.events
	queue[#queue + 1] = { listeners = listeners, x = p.x, y = p.y, z = p.z, localSpace = emitter.localSpace }
end

local function spawnParticle(instance, state, emitter, emitterTime, origin)
	if #state.particles >= emitter.max then return end
	local life = floatAt(emitter.life, emitterTime, random())
	if life <= 0 then return end
	local p = { t = 0, life = life }

	local lx, ly, lz = 0, 0, 0
	if emitter.location then lx, ly, lz = vectorAt(emitter.location, emitterTime, random(), random(), random()) end
	local vx, vy, vz = 0, 0, 0
	if emitter.velocity then vx, vy, vz = vectorAt(emitter.velocity, emitterTime, random(), random(), random()) end
	if emitter.radial then
		local speed = floatAt(emitter.radial, emitterTime, random())
		local length = sqrt(lx * lx + ly * ly + lz * lz)
		if length > 1e-6 then
			vx, vy, vz = vx + lx / length * speed, vy + ly / length * speed, vz + lz / length * speed
		end
	end

	p.sx, p.sy, p.sz = vectorAt(emitter.size, emitterTime, random(), random(), random())
	p.r, p.g, p.b = vectorAt(emitter.color, emitterTime, random(), random(), random())
	p.a = floatAt(emitter.alpha, emitterTime, random())
	p.roll = emitter.rotation and floatAt(emitter.rotation, emitterTime, random()) or 0
	p.spin = emitter.rotationRate and floatAt(emitter.rotationRate, emitterTime, random()) or 0
	-- Each particle follows its own point between an over-life curve's min and max.
	p.rs = { random(), random(), random(), random(), random(), random(), random(), random(), random(), random(), random(), random() }
	if emitter.sheet and not emitter.sheet.frames then
		p.frame = floor(random() * emitter.sheet.columns * emitter.sheet.rows)
	end
	if emitter.orbit then
		p.ox, p.oy, p.oz = vectorAt(emitter.orbit.offset, emitterTime, random(), random(), random())
		p.orx, p.ory, p.orz = vectorAt(emitter.orbit.rotation, emitterTime, random(), random(), random())
		p.osx, p.osy, p.osz = vectorAt(emitter.orbit.rate, emitterTime, random(), random(), random())
	end

	local pos, ang = frameOf(instance)
	if origin then
		-- Released at another particle's event: there, offset by the location in the effect's axes.
		local ox, oy, oz = origin.x, origin.y, origin.z
		if origin.localSpace and not emitter.localSpace then
			local world = LocalToWorld(Vector(ox, oy, oz), angle_zero, pos, ang)
			ox, oy, oz = world.x, world.y, world.z
		elseif emitter.localSpace and not origin.localSpace then
			local localPos = WorldToLocal(Vector(ox, oy, oz), angle_zero, pos, ang)
			ox, oy, oz = localPos.x, localPos.y, localPos.z
		end
		if not emitter.localSpace then
			local offset = Vector(lx, ly, lz)
			offset:Rotate(ang)
			lx, ly, lz = offset.x, offset.y, offset.z
		end
		lx, ly, lz = ox + lx, oy + ly, oz + lz
	elseif not emitter.localSpace then
		local world = LocalToWorld(Vector(lx, ly, lz), angle_zero, pos, ang)
		lx, ly, lz = world.x, world.y, world.z
	end
	if not emitter.localSpace then
		local velocity = Vector(vx, vy, vz)
		velocity:Rotate(ang)
		vx, vy, vz = velocity.x, velocity.y, velocity.z
		p.ang = Angle(ang.p, ang.y, ang.r)
	end
	p.x, p.y, p.z, p.vx, p.vy, p.vz = lx, ly, lz, vx, vy, vz
	state.particles[#state.particles + 1] = p
	raise(instance, emitter, "spawn", p)
end

local function worldPosition(instance, emitter, p)
	if not emitter.localSpace then return Vector(p.x, p.y, p.z) end
	local pos, ang = frameOf(instance)
	return LocalToWorld(Vector(p.x, p.y, p.z), angle_zero, pos, ang)
end

local function spawnAt(instance, emitter, emitterTime, count, origin)
	local state = instance.states[emitter.index]
	for _ = 1, count do spawnParticle(instance, state, emitter, emitterTime, origin) end
end

-- The emitter's cycle and its time within it.
local function clock(emitter, time)
	local emitterTime = max(time - emitter.delay, 0)
	local duration = emitter.duration
	if duration <= 0 then return 0, emitterTime end
	local cycle = floor(emitterTime / duration)
	return cycle, emitterTime - cycle * duration
end

-- Advances an emitter's schedule; returns whether it may still release particles.
local function schedule(instance, emitter, state, time, dt)
	if time < emitter.delay then return true end
	local duration = emitter.duration
	local cycle, cycleTime = clock(emitter, time)
	if emitter.loops > 0 and cycle >= emitter.loops then return false end
	if instance.stopping then return false end
	if cycle ~= state.cycle then
		state.cycle = cycle
		state.fired = {}
	end
	for i, burst in ipairs(emitter.bursts) do
		if not state.fired[i] and cycleTime >= burst[1] then
			state.fired[i] = true
			spawnAt(instance, emitter, cycleTime, random(burst[2], burst[3]))
		end
	end
	if emitter.rate then
		state.accumulated = state.accumulated + floatAt(emitter.rate, cycleTime, state.rateRandom) * dt
		local count = floor(state.accumulated)
		state.accumulated = state.accumulated - count
		spawnAt(instance, emitter, cycleTime, count)
	end
	if duration > 0 or emitter.rate then return true end
	-- Without a cycle, an emitter that only bursts is done once every burst has fired.
	for i in ipairs(emitter.bursts) do
		if not state.fired[i] then return true end
	end
	return false
end

local function simulate(instance, dt)
	instance.time = instance.time + dt
	local time = instance.time
	local alive = false
	local emitters = instance.effect.emitters
	for index, emitter in ipairs(emitters) do
		local state = instance.states[index]
		if schedule(instance, emitter, state, time, dt) then alive = true end
		local particles = state.particles
		local ax, ay, az = emitter.acceleration[1], emitter.acceleration[2], emitter.acceleration[3]
		if not emitter.localSpace then
			local accel = Vector(ax, ay, az)
			accel:Rotate(select(2, frameOf(instance)))
			ax, ay, az = accel.x, accel.y, accel.z
		end
		local drag = emitter.drag
		local i = 1
		while i <= #particles do
			local p = particles[i]
			p.t = p.t + dt
			local age = p.t / p.life
			if age >= 1 then
				raise(instance, emitter, "death", p)
				particles[i] = particles[#particles]
				particles[#particles] = nil
			else
				p.vx, p.vy, p.vz = p.vx + ax * dt, p.vy + ay * dt, p.vz + az * dt
				if drag > 0 then
					local keep = max(0, 1 - drag * dt)
					p.vx, p.vy, p.vz = p.vx * keep, p.vy * keep, p.vz * keep
				end
				local kx, ky, kz = 1, 1, 1
				if emitter.velocityOverLife then kx, ky, kz = vectorAt(emitter.velocityOverLife, age, p.rs[1], p.rs[2], p.rs[3]) end
				p.x, p.y, p.z = p.x + p.vx * kx * dt, p.y + p.vy * ky * dt, p.z + p.vz * kz * dt
				alive = true
				i = i + 1
			end
		end
	end
	-- Events reach their listeners after every emitter has ticked; ones raised meanwhile wait a frame.
	local events = instance.events
	instance.events = {}
	for _, event in ipairs(events) do
		for _, listener in ipairs(event.listeners) do
			local child = emitters[listener.emitter]
			local _, childTime = clock(child, time)
			spawnAt(instance, child, childTime, floor(floatAt(listener.count, childTime, random())), event)
			alive = true
		end
	end
	return alive
end

-- Drawing

local function particleValues(emitter, p)
	local age = min(p.t / p.life, 1)
	local rs = p.rs
	local sx, sy, sz = p.sx, p.sy, p.sz
	if emitter.sizeOverLife then
		local kx, ky, kz = vectorAt(emitter.sizeOverLife, age, rs[4], rs[5], rs[6])
		sx, sy, sz = sx * kx, sy * ky, sz * kz
	end
	local r, g, b = p.r, p.g, p.b
	if emitter.colorOverLife then r, g, b = vectorAt(emitter.colorOverLife, age, rs[7], rs[8], rs[9]) end
	local a = emitter.alphaOverLife and floatAt(emitter.alphaOverLife, age, rs[10]) or p.a
	local params = emitter.params
	local p1 = params[1] and floatAt(params[1], age, rs[11]) or 0
	local p2 = params[2] and floatAt(params[2], age, rs[12]) or 0
	local p3 = params[3] and floatAt(params[3], age, rs[11]) or 0
	local p4 = params[4] and floatAt(params[4], age, rs[12]) or 0
	return age, sx, sy, sz, r, g, b, a, p1, p2, p3, p4
end

local function orbitOffset(emitter, p, ang)
	if not emitter.orbit then return nil end
	local offset = Vector(p.ox, p.oy, p.oz)
	offset:Rotate(Angle(math.deg(p.ory + p.osy * p.t), math.deg(p.orz + p.osz * p.t), math.deg(p.orx + p.osx * p.t)))
	offset:Rotate(ang)
	return offset
end

local function setBlend(def)
	if def.blend == "additive" then
		render.OverrideBlend(true, BLEND_ONE, BLEND_ONE, BLENDFUNC_ADD)
	elseif def.blend == "translucent" then
		render.OverrideBlend(true, BLEND_SRC_ALPHA, BLEND_ONE_MINUS_SRC_ALPHA, BLENDFUNC_ADD)
	end
end

local function setTime(time)
	render.SetModelLighting(4, time % 1000, 0, 0)
end

local function drawMeshes(instance, emitter, state, time)
	local mat = material(emitter.material, "mesh")
	if not mat then return end
	local imesh = particleMesh(emitter.mesh, mat)
	if not imesh then return end
	local pos, ang = frameOf(instance)
	setBlend(emitter.material)
	for _, p in ipairs(state.particles) do
		local age, sx, sy, sz, r, g, b, a, p1, p2, p3, p4 = particleValues(emitter, p)
		render.SetModelLighting(0, r, g, b)
		render.SetModelLighting(1, a, age, 0)
		render.SetModelLighting(2, p1, p2, p3)
		render.SetModelLighting(3, p4, 0, 0)
		setTime(time)
		render.SetModelLighting(5, 0, 0, 0)
		if commitConstants() then
			local matrix = Matrix()
			if emitter.localSpace then
				matrix:SetTranslation(pos)
				matrix:SetAngles(ang)
				matrix:Translate(Vector(p.x, p.y, p.z))
			else
				matrix:SetTranslation(Vector(p.x, p.y, p.z))
				matrix:SetAngles(p.ang)
			end
			matrix:Scale(Vector(sx, sy, sz))
			render.SetMaterial(mat)
			cam.PushModelMatrix(matrix)
			imesh:Draw()
			cam.PopModelMatrix()
		end
	end
	render.OverrideBlend(false)
end

local function drawSprites(instance, emitter, state, time)
	local particles = state.particles
	if #particles == 0 then return end
	local mat = material(emitter.material, "sprite")
	if not mat then return end
	local _, ang = frameOf(instance)
	local eye = EyePos()
	local view = EyeAngles()
	local right, up = view:Right(), view:Up()
	local sheet = emitter.sheet
	setTime(time)
	if not commitConstants() then return end
	setBlend(emitter.material)
	render.SetMaterial(mat)
	-- Quads are built in world space; the constants' model left its (zero) scale as the model matrix.
	cam.PushModelMatrix(Matrix())
	mesh.Begin(MATERIAL_QUADS, #particles)
	local ok, err = pcall(function()
		for _, p in ipairs(particles) do
			local age, sx, sy, _, r, g, b, a, p1, p2, p3, p4 = particleValues(emitter, p)
			local center = worldPosition(instance, emitter, p)
			local orbit = orbitOffset(emitter, p, ang)
			if orbit then center = center + orbit end
			if emitter.cameraOffset then
				-- Drawn nearer the camera, in front of the surface the effect sits in.
				local toEye = eye - center
				local distance = toEye:Length()
				if distance > 1e-3 then center = center + toEye * (min(floatAt(emitter.cameraOffset, age, p.rs[2]), distance * 0.9) / distance) end
			end
			local axisX, axisY
			if emitter.alignment == 1 then
				local velocity = Vector(p.vx, p.vy, p.vz)
				if emitter.localSpace then velocity:Rotate(ang) end
				if velocity:LengthSqr() < 1e-8 then velocity = up end
				axisY = velocity:GetNormalized()
				axisX = axisY:Cross(center - eye):GetNormalized()
			else
				local roll = p.roll + p.spin * p.t
				local c, s = cos(roll), sin(roll)
				axisX = right * c + up * s
				axisY = up * c - right * s
			end
			local hx, hy = axisX * (sx * 0.5), axisY * (sy * 0.5)
			local u0, v0, u1, v1 = 0, 0, 1, 1
			if sheet then
				local frame = p.frame or floor(floatAt(sheet.frames, age, p.rs[1]))
				local count = sheet.columns * sheet.rows
				frame = ((frame % count) + count) % count
				local column, row = frame % sheet.columns, floor(frame / sheet.columns)
				u0, u1 = column / sheet.columns, (column + 1) / sheet.columns
				v0, v1 = row / sheet.rows, (row + 1) / sheet.rows
			end
			local color = Vector(r, g, b)
			local corners = {
				{ center - hx - hy, u0, v1 }, { center + hx - hy, u1, v1 },
				{ center + hx + hy, u1, v0 }, { center - hx + hy, u0, v0 },
			}
			for _, corner in ipairs(corners) do
				mesh.Position(corner[1])
				mesh.Normal(color)
				mesh.Color(255, 255, 255, 255)
				mesh.TexCoord(0, corner[2], corner[3])
				mesh.TexCoord(1, a, age)
				mesh.TexCoord(2, p1, p2)
				mesh.TexCoord(3, p3, p4)
				mesh.AdvanceVertex()
			end
		end
	end)
	mesh.End()
	cam.PopModelMatrix()
	render.OverrideBlend(false)
	if not ok then ErrorNoHalt("[GMConverter] Effect draw failed: " .. tostring(err) .. "\n") end
end

local function draw(instance)
	local time = CurTime()
	render.SuppressEngineLighting(true)
	render.OverrideDepthEnable(true, false)
	for index, emitter in ipairs(instance.effect.emitters) do
		local state = instance.states[index]
		if #state.particles > 0 then
			if emitter.mesh then drawMeshes(instance, emitter, state, time) else drawSprites(instance, emitter, state, time) end
		end
	end
	render.OverrideDepthEnable(false, false)
	render.SuppressEngineLighting(false)
	render.ResetModelLighting(1, 1, 1)
end

--- Starts an effect on an entity's attachment (by name), or at pos/ang without one; returns the instance.
function FX.Play(name, entity, attachmentName, viewModel, pos, ang)
	local effect = FX.effects[name]
	if not effect then return nil end
	if not effect.linked then
		effect.linked = true
		for index, emitter in ipairs(effect.emitters) do
			for _, eventSpawn in ipairs(emitter.events or {}) do
				for _, source in ipairs(eventSpawn.sources) do
					local from = effect.emitters[source[1]]
					if from then
						from.listeners = from.listeners or {}
						from.listeners[source[2]] = from.listeners[source[2]] or {}
						table.insert(from.listeners[source[2]], { emitter = index, count = eventSpawn.count })
					end
				end
			end
		end
	end
	local instance = {
		effect = effect, name = name, entity = entity, viewModel = viewModel and true or false,
		attachment = IsValid(entity) and attachmentName and entity:LookupAttachment(attachmentName) or nil,
		pos = pos, ang = ang, time = 0, states = {}, events = {}, last = CurTime(),
	}
	for index in ipairs(effect.emitters) do
		instance.states[index] = { particles = {}, accumulated = 0, rateRandom = random(), fired = {}, cycle = -1 }
	end
	FX.active[#FX.active + 1] = instance
	return instance
end

--- Stops an instance's emitters; particles already released live out their lives.
function FX.Stop(instance)
	if instance then instance.stopping = true end
end

local function step(instance)
	local frame = FrameNumber()
	if instance.frame == frame then return instance.alive end
	instance.frame = frame
	local now = CurTime()
	local dt = math.Clamp(now - instance.last, 0, 0.1)
	instance.last = now
	instance.alive = simulate(instance, dt)
	return instance.alive
end

-- View models: start the effects a sequence passes since the last frame; loops stop with the sequence.
local watched = setmetatable({}, { __mode = "k" })
local function watch(vm)
	local events = FX.models[string.lower(vm:GetModel() or "")]
	if not events then return end
	local sequence = vm:GetSequence()
	local time = vm:GetCycle() * vm:SequenceDuration(sequence)
	local last = watched[vm]
	if last and last.sequence ~= sequence then
		for _, instance in ipairs(FX.active) do
			if instance.entity == vm then FX.Stop(instance) end
		end
	end
	local from = (last and last.sequence == sequence and last.time <= time) and last.time or -1
	watched[vm] = { sequence = sequence, time = time }
	for _, event in ipairs(events[vm:GetSequenceName(sequence)] or {}) do
		if event[1] > from and event[1] <= time then FX.Play(event[2], vm, event[3], true) end
	end
end

local function drawPass(viewModel, entity)
	for i = #FX.active, 1, -1 do
		local instance = FX.active[i]
		if instance.viewModel == viewModel and (not viewModel or instance.entity == entity) then
			local valid = instance.entity == nil or IsValid(instance.entity)
			if valid and step(instance) then
				draw(instance)
			else
				table.remove(FX.active, i)
			end
		end
	end
end

hook.Add("PostDrawViewModel", "GMConverterFX", function(vm)
	if not IsValid(vm) then return end
	-- Shader libraries such as GShader draw the view model again into their depth target; effects don't belong there.
	local target = render.GetRenderTarget()
	if target and target:GetName() == "_rt_resolvedfullframedepth" then return end
	watch(vm)
	drawPass(true, vm)
end)

hook.Add("PostDrawTranslucentRenderables", "GMConverterFX", function(depth, skybox, skybox3d)
	if depth or skybox or skybox3d then return end
	drawPass(false)
end)
